import {readFile,writeFile} from 'node:fs/promises';import {createHash} from 'node:crypto';
const phase=process.argv[2],env=process.argv[3],refs={PROD:'YOUR_PROJECT_REF',DEV:'YOUR_PROJECT_REF'},ledgers={PROD:454,DEV:432};if(!refs[env]||!['prepare','dry-run','apply'].includes(phase))throw Error('Explicit phase/target required');
const pr='./LOCAL_USER/AppData/Local/FVI-QA-Private-20260925',base=pr+'/FVI-REGISTRATION-RECOVERY-'+env+'-RELEASE-20261004-v1',version='20261004082000';
const folder='./LOCAL_USER/AppData/Local/Temp/fvi-batch4-candidate-20260928/output/faraday-registration-rebase-20261004-v1/forward-sql';
const sha=x=>createHash('sha256').update(x).digest('hex'),q=x=>"'"+x.replaceAll("'","''")+"'";
const v=await readFile('./.private/CREDENTIALS.md','utf8');const a=v.indexOf('<!-- FVI_CANONICAL_OPERATIONAL_CREDENTIALS_BEGIN -->'),b=v.indexOf('<!-- FVI_CANONICAL_OPERATIONAL_CREDENTIALS_END -->');if(a<0||b<=a)throw Error('FVI vault boundary missing');const token=v.slice(a,b).split(/\r?\n/).find(x=>/^\|\s*`SUPABASE_ACCESS_TOKEN`\s*\|/.test(x))?.split('|')[2]?.trim().replace(/^`|`$/g,'');if(!/^sbp_/.test(token??''))throw Error('Management unavailable');
async function query(sql,ro){const r=await fetch(`https://api.supabase.com/v1/projects/${refs[env]}/database/query`,{method:'POST',headers:{authorization:`Bearer ${token}`,'content-type':'application/json'},body:JSON.stringify({query:sql,read_only:ro}),signal:AbortSignal.timeout(110000)});const raw=await r.text();if(!r.ok){const p=base+'-'+phase+'-ERROR-'+Date.now()+'.json';await writeFile(p,JSON.stringify({at:new Date().toISOString(),http:r.status,raw},null,2),{flag:'wx'});throw Error('HTTP'+r.status+'; private diagnosis '+p);}return {raw,rows:JSON.parse(raw)};}
const identity="SELECT current_setting('server_version_num') AS engine,(SELECT count(*) FROM supabase_migrations.schema_migrations)::int AS ledger,(SELECT max(version::text) FROM supabase_migrations.schema_migrations) AS latest";
if(phase==='prepare'){
 const source=await readFile(folder+'/signup-invitation-recovery.sql','utf8');if(sha(source)!=='f8285a42ea7dfb1424989643f2ff585f1428b856fd8c6c6be884c08cfe20ee63')throw Error('Frozen18-case recovery source drift');
 const guard=await readFile(folder+'/parent-preapply-guard.sql','utf8');const before=await query(identity,true);if(before.rows[0]?.ledger!==ledgers[env]||before.rows[0]?.latest!=='20261004081000'||before.rows[0]?.engine!=='170006')throw Error('Actual target identity changed');
 const contract=await query("SELECT md5(pg_get_functiondef('public.rate_limit_hit(text,integer,integer)'::regprocedure)) AS rate_md5,md5(pg_get_functiondef('public.request_tenant_admission()'::regprocedure)) AS admission_md5,(SELECT encode(sha256(convert_to(statements[1],'UTF8')),'hex') FROM supabase_migrations.schema_migrations WHERE version='20261004033000' AND array_length(statements,1)=1) AS pt409_source",true);
 if(contract.rows[0]?.rate_md5!=='65b9ba128babc33c3fbf58f0d7c5740d'||contract.rows[0]?.admission_md5!=='420f64fafcdd43a56b1f6e03def4b447'||contract.rows[0]?.pt409_source!=='12422f6fbc3c2a53efdf4c59f45edc58bd9a10901fedbca574b166184df25cd6')throw Error('Actual registration dependency/source proof changed');
 let sql="BEGIN;SET LOCAL lock_timeout='5s';SET LOCAL statement_timeout='90s';\n"+guard+'\n';
 sql+=`LOCK TABLE supabase_migrations.schema_migrations IN SHARE ROW EXCLUSIVE MODE;DO $current$ BEGIN IF (SELECT count(*) FROM supabase_migrations.schema_migrations)<>${ledgers[env]} OR (SELECT max(version::text) FROM supabase_migrations.schema_migrations)<>'20261004081000' OR EXISTS(SELECT 1 FROM supabase_migrations.schema_migrations WHERE version=${q(version)}) THEN RAISE EXCEPTION 'registration exact ledger/collision drift';END IF;IF md5(pg_get_functiondef('public.rate_limit_hit(text,integer,integer)'::regprocedure))<>'65b9ba128babc33c3fbf58f0d7c5740d' OR md5(pg_get_functiondef('public.request_tenant_admission()'::regprocedure))<>'420f64fafcdd43a56b1f6e03def4b447' THEN RAISE EXCEPTION 'registration dependency drift';END IF;END $current$;\n`;
 sql+="CREATE TEMP TABLE _reg_oldledger AS SELECT encode(sha256(convert_to(jsonb_agg(to_jsonb(m) ORDER BY version)::text,'UTF8')),'hex') AS sha FROM supabase_migrations.schema_migrations m;CREATE TEMP TABLE _reg_oldrows(name text,n bigint,sha text);\n";
 for(const name of ['tenant_email_domains','tenant_signup_requests'])sql+=`LOCK TABLE public.${name} IN SHARE MODE;INSERT INTO _reg_oldrows SELECT ${q(name)},count(*),encode(sha256(convert_to(coalesce(jsonb_agg(to_jsonb(t) ORDER BY to_jsonb(t)::text),'[]'::jsonb)::text,'UTF8')),'hex') FROM public.${name} t;\n`;
 sql+="CREATE TEMP TABLE _reg_oldfunctions AS SELECT p.oid,p.prosrc,p.proowner,p.proacl,p.proconfig,p.prosecdef,p.proargnames,p.proargtypes,pg_get_function_result(p.oid) AS result FROM pg_proc p WHERE p.oid IN ('public.rate_limit_hit(text,integer,integer)'::regprocedure,'public.request_tenant_admission()'::regprocedure);\n";
 sql+=source+"\nDO $preserve$ DECLARE r record;n bigint;v text;BEGIN FOR r IN SELECT * FROM _reg_oldrows LOOP EXECUTE format('SELECT count(*),encode(sha256(convert_to(coalesce(jsonb_agg(to_jsonb(t) ORDER BY to_jsonb(t)::text),''[]''::jsonb)::text,''UTF8'')),''hex'') FROM public.%I t',r.name) INTO n,v;IF n IS DISTINCT FROM r.n OR v IS DISTINCT FROM r.sha THEN RAISE EXCEPTION 'registration changed old rows';END IF;END LOOP;IF EXISTS(SELECT 1 FROM _reg_oldfunctions o LEFT JOIN pg_proc p ON p.oid=o.oid WHERE p.oid IS NULL OR ROW(p.prosrc,p.proowner,p.proacl,p.proconfig,p.prosecdef,p.proargnames,p.proargtypes,pg_get_function_result(p.oid)) IS DISTINCT FROM ROW(o.prosrc,o.proowner,o.proacl,o.proconfig,o.prosecdef,o.proargnames,o.proargtypes,o.result)) THEN RAISE EXCEPTION 'registration changed old source/authority/ABI';END IF;IF has_table_privilege('anon','public.signup_invitation_attempts','SELECT') OR has_table_privilege('authenticated','public.signup_invitation_attempts','SELECT') OR has_table_privilege('service_role','public.signup_invitation_attempts','SELECT') THEN RAISE EXCEPTION 'recovery table exposed';END IF;END $preserve$;\n";
 sql+=`INSERT INTO supabase_migrations.schema_migrations(version,name,statements) VALUES(${q(version)},'durable_signup_invitation_recovery',ARRAY[${q(source)}]::text[]);DO $registered$ BEGIN IF (SELECT count(*) FROM supabase_migrations.schema_migrations)<>${ledgers[env]+1} OR (SELECT max(version::text) FROM supabase_migrations.schema_migrations)<>${q(version)} OR (SELECT encode(sha256(convert_to(jsonb_agg(to_jsonb(m) ORDER BY version)::text,'UTF8')),'hex') FROM supabase_migrations.schema_migrations m WHERE version<>${q(version)}) IS DISTINCT FROM (SELECT sha FROM _reg_oldledger) THEN RAISE EXCEPTION 'registration old ledger changed';END IF;END $registered$;SELECT true AS registration_checks_passed;\n`;
 const p={at:new Date().toISOString(),environment:env,version,initialLedger:ledgers[env],expectedLedger:ledgers[env]+1,sourceSha256:sha(source),contract:contract.rows,dryRunSha256:sha(sql+'ROLLBACK;\n'),applySha256:sha(sql+"NOTIFY pgrst,'reload schema';COMMIT;\n")};await writeFile(base+'-DRY-RUN.sql',sql+'ROLLBACK;\n',{flag:'wx'});await writeFile(base+'-APPLY.sql',sql+"NOTIFY pgrst,'reload schema';COMMIT;\n",{flag:'wx'});await writeFile(base+'-PREPARED.json',JSON.stringify(p,null,2),{flag:'wx'});console.log(JSON.stringify({environment:env,prepared:base+'-PREPARED.json',sourceSha256:p.sourceSha256}));
}else{
 const p=JSON.parse(await readFile(base+'-PREPARED.json','utf8')),sql=await readFile(base+(phase==='dry-run'?'-DRY-RUN.sql':'-APPLY.sql'),'utf8');if(sha(sql)!==(phase==='dry-run'?p.dryRunSha256:p.applySha256))throw Error('Immutable packet changed');if(phase==='apply'){const d=JSON.parse(await readFile(base+'-DRY-RUN-RECEIPT.json','utf8'));if(!d.rollbackVerified||d.packetSha256!==p.dryRunSha256)throw Error('Exact rollback proof absent');try{await readFile(base+'-APPLY-RECEIPT.json');throw Error('Already committed; readback only');}catch(e){if(e.code!=='ENOENT')throw e;}}
 const before=await query(identity,true);if(before.rows[0]?.ledger!==ledgers[env]||before.rows[0]?.latest!=='20261004081000')throw Error('Mutable identity changed');const execution=await query(sql,false),after=await query(identity,true);const ok=execution.rows.some(x=>x.registration_checks_passed===true)&&(phase==='dry-run'?before.raw===after.raw:after.rows[0]?.ledger===p.expectedLedger&&after.rows[0]?.latest===version);await writeFile(base+(phase==='dry-run'?'-DRY-RUN-RECEIPT.json':'-APPLY-RECEIPT.json'),JSON.stringify({at:new Date().toISOString(),environment:env,phase,packetSha256:sha(sql),before,execution,after,rollbackVerified:phase==='dry-run'&&ok,commitVerified:phase==='apply'&&ok,emailSent:false,hostedWorkflowAcceptance:false},null,2),{flag:'wx'});if(!ok)throw Error('Exact postconditions unproven');console.log(JSON.stringify({environment:env,phase,verified:ok,ledger:after.rows[0].ledger,latest:after.rows[0].latest}));
}
